--
-- Structure de la table `hesitation_critere`
--

CREATE TABLE `hesitation_critere` (
  `id_critere` int(11) NOT NULL,
  `code` varchar(50) NOT NULL,
  `nom` varchar(150) NOT NULL,
  `categorie` enum('attirance','force','attente','decision') NOT NULL,
  `actif` tinyint(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `hesitation_critere`
--

INSERT INTO `hesitation_critere` (`id_critere`, `code`, `nom`, `categorie`, `actif`) VALUES
(1, 'contenu', 'Contenu du métier ou de la formation', 'attirance', 1),
(2, 'sens', 'Sens et utilité', 'attirance', 1),
(3, 'debouches', 'Perspectives professionnelles', 'attirance', 1),
(4, 'conditions', 'Conditions de travail', 'attirance', 1),
(5, 'progression', 'Possibilités de progression', 'attirance', 1),
(6, 'analyse', 'Analyse', 'force', 1),
(7, 'creation', 'Créativité', 'force', 1),
(8, 'relation', 'Relation et accompagnement', 'force', 1),
(9, 'organisation', 'Organisation', 'force', 1),
(10, 'action', 'Initiative et passage à l’action', 'force', 1),
