--
-- Structure de la table `metier`
--

CREATE TABLE `metier` (
  `id_metier` int(11) NOT NULL,
  `nom` varchar(150) NOT NULL,
  `description` text NOT NULL,
  `presentation` text DEFAULT NULL,
  `competences` text DEFAULT NULL,
  `secteur` varchar(100) NOT NULL,
  `niveau_etude` varchar(100) NOT NULL,
  `salaire_min` decimal(12,2) DEFAULT NULL,
  `salaire_max` decimal(12,2) DEFAULT NULL,
  `profil_riasec` varchar(3) NOT NULL,
  `tendance` varchar(100) DEFAULT NULL,
  `accessible_test` tinyint(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `metier`
--

INSERT INTO `metier` (`id_metier`, `nom`, `description`, `presentation`, `competences`, `secteur`, `niveau_etude`, `salaire_min`, `salaire_max`, `profil_riasec`, `tendance`, `accessible_test`) VALUES
(1, 'Développeur Web', 'Création de sites et applications web', 'Le développeur web conçoit, développe et maintient des sites internet et des applications web. Il transforme les besoins des utilisateurs en solutions numériques grâce aux technologies du développement web.', 'HTML, CSS, JavaScript, PHP, bases de données, frameworks web, logique de programmation, résolution de problèmes', 'Informatique', 'Bac+3', 300000.00, 1500000.00, 'IRA', 'Forte croissance', 1),
(2, 'Data Scientist', 'Analyse de données et intelligence artificielle', 'Le data scientist analyse de grandes quantités de données afin d\'extraire des informations utiles et aider les organisations à prendre de meilleures décisions. Il utilise les statistiques, la programmation et l\'intelligence artificielle.', 'Python, statistiques, analyse de données, machine learning, intelligence artificielle, bases de données, visualisation de données', 'Informatique', 'Bac+5', 500000.00, 2000000.00, 'IRC', 'Très forte croissance', 1),
(3, 'Ingénieur Génie Civil', 'Construction de bâtiments et infrastructures', 'L\'ingénieur génie civil conçoit, planifie et supervise la réalisation des infrastructures comme les bâtiments, les routes et les ouvrages publics. Il veille au respect des normes techniques et de sécurité.', 'Conception technique, calculs de structures, AutoCAD, gestion de projet, résistance des matériaux, analyse des plans, travail en équipe', 'Génie Civil / BTP', 'Bac+5', 400000.00, 1800000.00, 'RIC', 'En croissance', 0),
(4, 'Médecin', 'Diagnostic et traitement des patients', 'Le médecin diagnostique, traite et accompagne les patients afin de préserver leur santé. Il utilise ses connaissances scientifiques et médicales pour prévenir et soigner les maladies.', 'Diagnostic médical, connaissances en sciences de la santé, écoute, communication, analyse clinique, prise de décision, éthique professionnelle', 'Santé', 'Bac+7+', 600000.00, 3000000.00, 'ISR', 'Stable', 1),
(5, 'Avocat', 'Défense juridique et conseils', 'L\'avocat conseille et représente ses clients dans les affaires juridiques. Il analyse les lois, prépare des dossiers et défend les intérêts des personnes ou des organisations devant les institutions compétentes.', 'Connaissance du droit, analyse juridique, argumentation, rédaction juridique, communication, négociation, esprit critique', 'Administration publique, Économie et Sciences sociales', 'Bac+5', 300000.00, 2000000.00, 'ESA', 'Stable', 1),
(6, 'Comptable', 'Gestion des finances et comptabilité', 'Le comptable assure la gestion des opérations financières d\'une organisation. Il enregistre les transactions, prépare les documents comptables et contribue au suivi de la situation financière.', 'Comptabilité générale, analyse financière, Excel, logiciels comptables, rigueur, organisation, gestion des chiffres', 'Comptabilité, Fiscalité et Expertise', 'Bac+3', 250000.00, 1200000.00, 'CER', 'Stable', 0),
(7, 'Marketeur', 'Stratégies marketing et communication', 'Le marketeur étudie les besoins des consommateurs et développe des stratégies pour promouvoir des produits ou services. Il participe à la communication, à la publicité et au développement commercial.', 'Étude de marché, communication, stratégie marketing, réseaux sociaux, analyse des données, créativité, gestion de projet', 'Commerce, Marketing et Communication', 'Bac+3', 250000.00, 1500000.00, 'EAS', 'Forte croissance', 0),
(8, 'Administrateur Réseau', 'Gestion des réseaux informatiques', 'L\'administrateur réseau installe, configure et assure la maintenance des réseaux informatiques d\'une organisation. Il garantit la disponibilité, la sécurité et la performance des systèmes connectés.', 'Configuration réseau, TCP/IP, cybersécurité, systèmes Linux et Windows, maintenance informatique, résolution de problèmes, surveillance réseau', 'Télécommunications et Réseaux', 'Bac+3', 300000.00, 1400000.00, 'IRC', 'Forte croissance', 1),
(9, 'Data Analyst', 'Analyse et interprétation des données pour aider à la prise de décision', 'Le Data Analyst collecte, nettoie, analyse et interprète les données afin de produire des informations utiles aux organisations. Il utilise les statistiques, les outils informatiques et la visualisation de données pour aider les entreprises, administrations et institutions à prendre de meilleures décisions.', 'SQL, Excel avancé, Python, R, statistiques, analyse de données, visualisation de données, Power BI, bases de données', 'Informatique', 'Bac+3', 350000.00, 1500000.00, 'IRC', 'Très forte croissance', 1),
(10, 'Ingénieur Logiciel', 'Conception et développement de solutions logicielles', 'L’ingénieur logiciel conçoit, développe et maintient des applications informatiques complexes. Il participe à toutes les étapes de création d’un logiciel, depuis l’analyse des besoins jusqu’au déploiement et à l’amélioration des solutions.', 'Programmation, architecture logicielle, Java, Python, JavaScript, bases de données, conception système, tests logiciels', 'Informatique', 'Bac+5', 500000.00, 2000000.00, 'IRC', 'Très forte croissance', 1),
(11, 'Développeur Mobile', 'Création d’applications mobiles pour smartphones et tablettes', 'Le développeur mobile conçoit et développe des applications destinées aux appareils mobiles. Il transforme des idées et besoins utilisateurs en applications performantes adaptées aux systèmes Android et iOS.', 'Java, Kotlin, Flutter, React Native, développement Android, développement iOS, API, bases de données', 'Informatique', 'Bac+3', 300000.00, 1500000.00, 'IRA', 'Forte croissance', 0),
(12, 'Développeur Backend', 'Développement de la logique serveur des applications', 'Le développeur backend crée et maintient la partie serveur des applications web et mobiles. Il développe les API, gère les bases de données et assure le bon fonctionnement des échanges entre les différentes parties d’une application.', 'PHP, Python, Java, Node.js, API REST, bases de données, sécurité serveur, architecture backend', 'Informatique', 'Bac+3', 350000.00, 1700000.00, 'IRC', 'Forte croissance', 0),
(13, 'Développeur Frontend', 'Création des interfaces visibles des applications web', 'Le développeur frontend développe les interfaces avec lesquelles les utilisateurs interagissent. Il transforme les maquettes et besoins graphiques en expériences numériques modernes, rapides et accessibles.', 'HTML, CSS, JavaScript, React, interfaces utilisateur, responsive design, intégration web', 'Informatique', 'Bac+3', 300000.00, 1500000.00, 'IAR', 'Forte croissance', 0),
(14, 'Expert Cybersécurité', 'Protection des systèmes informatiques contre les menaces numériques', 'L’expert cybersécurité analyse les risques, protège les systèmes informatiques et met en place des solutions pour prévenir les attaques numériques. Il intervient auprès des entreprises, banques, administrations et organisations sensibles.', 'Sécurité informatique, réseaux, Linux, cryptographie, tests d’intrusion, gestion des risques, cybersécurité', 'Informatique', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Très forte croissance', 1),
(15, 'Administrateur Base de Données', 'Gestion et sécurisation des bases de données', 'L’administrateur base de données assure l’installation, la maintenance, l’organisation et la sécurité des bases de données utilisées par les organisations. Il garantit la disponibilité et la fiabilité des informations.', 'SQL, MySQL, PostgreSQL, administration base de données, sauvegarde, sécurité des données, optimisation', 'Informatique', 'Bac+3', 350000.00, 1800000.00, 'ICR', 'Forte croissance', 1),
(16, 'Ingénieur Cloud et DevOps', 'Gestion des infrastructures numériques et automatisation des déploiements', 'L’ingénieur Cloud et DevOps automatise, déploie et supervise les applications sur des infrastructures modernes. Il améliore la fiabilité, la performance et la disponibilité des services numériques.', 'Cloud computing, Linux, Docker, Kubernetes, CI/CD, AWS, administration système, automatisation', 'Informatique', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Très forte croissance', 1),
(17, 'UX/UI Designer', 'Conception d’expériences et interfaces numériques', 'L’UX/UI Designer conçoit des interfaces numériques simples, accessibles et adaptées aux besoins des utilisateurs. Il travaille sur l’apparence, l’ergonomie et l’expérience globale des applications et plateformes numériques.', 'Figma, design graphique, expérience utilisateur, prototypage, recherche utilisateur, ergonomie, créativité', 'Informatique', 'Bac+3', 250000.00, 1500000.00, 'ASI', 'Forte croissance', 1),
(18, 'Ingénieur Intelligence Artificielle', 'Conception de systèmes intelligents utilisant les données et les algorithmes', 'L’ingénieur en intelligence artificielle conçoit et développe des solutions capables d’analyser des données, d’apprendre automatiquement et d’automatiser certaines tâches. Il travaille sur des domaines comme la reconnaissance d’images, le traitement du langage, les systèmes prédictifs et les applications intelligentes.', 'Python, machine learning, deep learning, statistiques, mathématiques, intelligence artificielle, TensorFlow, PyTorch, analyse de données', 'Informatique', 'Bac+5', 600000.00, 3000000.00, 'IRC', 'Très forte croissance', 1),
(19, 'Ingénieur Data / Big Data', 'Gestion et analyse de grandes quantités de données', 'L’ingénieur Data et Big Data conçoit des infrastructures permettant de collecter, stocker et traiter de grands volumes de données. Il travaille avec les entreprises afin de rendre les données exploitables pour la décision stratégique et l’innovation.', 'Python, SQL, Big Data, Hadoop, Spark, bases de données, architecture des données, cloud computing, traitement de données', 'Informatique', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Très forte croissance', 0),
(20, 'Administrateur Systèmes', 'Gestion et maintenance des systèmes informatiques', 'L’administrateur systèmes assure l’installation, la configuration et la maintenance des serveurs et systèmes informatiques d’une organisation. Il garantit la disponibilité, la sécurité et le bon fonctionnement des infrastructures techniques.', 'Linux, Windows Server, administration système, virtualisation, serveurs, sécurité informatique, sauvegarde, supervision', 'Informatique', 'Bac+3', 300000.00, 1800000.00, 'RIC', 'Forte croissance', 1),
(21, 'Ingénieur Systèmes et Réseaux', 'Conception et supervision des infrastructures informatiques', 'L’ingénieur systèmes et réseaux conçoit, déploie et supervise les infrastructures réseau et système des organisations. Il assure la performance, la disponibilité et la sécurité des équipements informatiques.', 'Réseaux, TCP/IP, routage, commutation, Linux, cybersécurité, administration réseau, infrastructure informatique', 'Informatique', 'Bac+5', 500000.00, 2200000.00, 'RIC', 'Forte croissance', 0),
(22, 'Technicien Support Informatique', 'Assistance technique et maintenance des équipements informatiques', 'Le technicien support informatique accompagne les utilisateurs dans la résolution de leurs problèmes techniques. Il installe, configure et entretient les équipements informatiques afin d’assurer la continuité des activités.', 'Maintenance informatique, installation logiciels, dépannage, systèmes Windows, réseaux, assistance utilisateur, diagnostic technique', 'Informatique', 'Bac+2', 200000.00, 800000.00, 'RCS', 'Stable', 1),
(23, 'Analyste Cybersécurité SOC', 'Surveillance et analyse des menaces informatiques', 'L’analyste cybersécurité SOC surveille les systèmes informatiques afin de détecter, analyser et répondre aux incidents de sécurité. Il participe à la protection des organisations contre les attaques numériques.', 'Sécurité informatique, analyse des incidents, SIEM, réseaux, Linux, tests de sécurité, gestion des vulnérabilités, cybersécurité', 'Informatique', 'Bac+3', 400000.00, 2000000.00, 'IRC', 'Très forte croissance', 0),
(24, 'Pharmacien', 'Préparation, contrôle et dispensation des médicaments', 'Le pharmacien est un professionnel de santé spécialisé dans les médicaments. Il assure leur préparation, leur contrôle, leur distribution et conseille les patients sur leur utilisation. Il peut travailler en pharmacie, dans les hôpitaux, les laboratoires ou l’industrie pharmaceutique.', 'Pharmacologie, sciences médicales, gestion des médicaments, conseil patient, biologie, réglementation sanitaire, communication', 'Santé', 'Bac+5', 400000.00, 2500000.00, 'ICS', 'Stable', 1),
(25, 'Infirmier', 'Soins médicaux et accompagnement des patients', 'L’infirmier assure les soins aux patients, accompagne leur prise en charge et collabore avec les médecins et les autres professionnels de santé. Il intervient dans les hôpitaux, cliniques, centres de santé et programmes de santé publique.', 'Soins infirmiers, surveillance médicale, hygiène, communication, premiers secours, accompagnement patient, organisation', 'Santé', 'Bac+3', 200000.00, 1000000.00, 'SRC', 'Forte croissance', 1),
(26, 'Sage-femme', 'Accompagnement médical des femmes enceintes et suivi des naissances', 'La sage-femme accompagne les femmes pendant la grossesse, l’accouchement et la période postnatale. Elle joue un rôle essentiel dans la santé maternelle et infantile.', 'Santé maternelle, suivi grossesse, accouchement, soins du nouveau-né, communication, prévention sanitaire', 'Santé', 'Bac+3', 250000.00, 1200000.00, 'SRC', 'Forte croissance', 1),
(27, 'Dentiste', 'Diagnostic et traitement des problèmes bucco-dentaires', 'Le dentiste diagnostique et traite les maladies des dents et de la bouche. Il réalise des soins, prévient les problèmes dentaires et accompagne les patients dans leur santé bucco-dentaire.', 'Chirurgie dentaire, diagnostic, anatomie, soins dentaires, communication patient, hygiène médicale', 'Santé', 'Bac+6', 500000.00, 3000000.00, 'IRS', 'Stable', 1),
(28, 'Biologiste Médical', 'Réalisation et interprétation des analyses médicales', 'Le biologiste médical supervise les analyses réalisées en laboratoire afin d’aider au diagnostic des maladies. Il travaille avec des équipements scientifiques et participe au suivi médical des patients.', 'Biologie médicale, analyses laboratoire, microbiologie, biochimie, recherche, équipements médicaux, qualité', 'Santé', 'Bac+5', 400000.00, 2000000.00, 'ICR', 'Forte croissance', 1),
(29, 'Technicien de Laboratoire Médical', 'Analyse d’échantillons biologiques en laboratoire', 'Le technicien de laboratoire médical réalise des analyses sur des prélèvements biologiques sous la supervision de professionnels spécialisés. Il contribue au diagnostic et au suivi des patients.', 'Analyses médicales, microbiologie, biologie, équipements laboratoire, prélèvements, procédures qualité', 'Santé', 'Bac+2', 200000.00, 900000.00, 'RIC', 'Forte croissance', 1),
(30, 'Vétérinaire', 'Prévention et traitement des maladies animales', 'Le vétérinaire assure la santé des animaux, réalise des diagnostics et accompagne les éleveurs dans la prévention des maladies animales. Il joue également un rôle dans la sécurité alimentaire.', 'Médecine animale, diagnostic, élevage, chirurgie animale, santé publique, biologie, communication', 'Santé', 'Bac+6', 400000.00, 2000000.00, 'IRS', 'En croissance', 1),
(31, 'Psychologue', 'Accompagnement psychologique et analyse du comportement humain', 'Le psychologue accompagne les personnes rencontrant des difficultés émotionnelles, sociales ou psychologiques. Il utilise des méthodes d’écoute et d’analyse afin d’aider les patients à améliorer leur bien-être.', 'Psychologie, écoute, communication, analyse comportementale, accompagnement, entretien clinique', 'Santé', 'Bac+5', 250000.00, 1500000.00, 'SIA', 'Forte croissance', 1),
(32, 'Nutritionniste / Diététicien', 'Conseil alimentaire et accompagnement nutritionnel', 'Le nutritionniste accompagne les personnes dans l’amélioration de leur alimentation et leur santé. Il intervient dans la prévention des maladies liées à la nutrition et dans l’éducation alimentaire.', 'Nutrition, alimentation, santé publique, conseil, analyse alimentaire, prévention, communication', 'Santé', 'Bac+3', 250000.00, 1500000.00, 'SIC', 'En croissance', 1),
(33, 'Kinésithérapeute', 'Rééducation physique et récupération fonctionnelle des patients', 'Le kinésithérapeute accompagne les patients dans leur récupération après une blessure, une maladie ou une intervention médicale. Il utilise des techniques de rééducation afin d’améliorer la mobilité et l’autonomie des personnes.', 'Rééducation, anatomie, physiothérapie, exercices thérapeutiques, accompagnement patient, techniques manuelles', 'Santé', 'Bac+3', 300000.00, 1500000.00, 'SRI', 'Forte croissance', 1),
(34, 'Ingénieur Biomédical', 'Conception, maintenance et gestion des équipements médicaux', 'L’ingénieur biomédical assure le développement, l’installation, la maintenance et l’amélioration des équipements utilisés dans les établissements de santé. Il travaille à l’interface entre les technologies de l’ingénierie et les besoins médicaux afin d’améliorer la qualité des soins.', 'Ingénierie biomédicale, électronique, maintenance médicale, équipements hospitaliers, informatique médicale, gestion de projet, analyse technique', 'Santé', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Très forte croissance', 1),
(35, 'Épidémiologiste', 'Analyse et surveillance des maladies dans les populations', 'L’épidémiologiste étudie la fréquence, les causes et la propagation des maladies afin d’aider à mettre en place des stratégies de prévention et de contrôle sanitaire. Il intervient dans les programmes de santé publique, les organismes de recherche et les institutions sanitaires.', 'Statistiques, analyse de données, santé publique, recherche, méthodologie scientifique, prévention des maladies, collecte de données', 'Santé', 'Bac+5', 400000.00, 2000000.00, 'ICS', 'Forte croissance', 0),
(36, 'Chercheur en Sciences de la Santé', 'Recherche scientifique dans le domaine médical et biologique', 'Le chercheur en sciences de la santé réalise des travaux scientifiques afin de mieux comprendre les maladies, développer de nouveaux traitements et améliorer les connaissances médicales. Il peut travailler dans les universités, laboratoires et instituts de recherche.', 'Recherche scientifique, biologie, méthodologie expérimentale, analyse scientifique, rédaction scientifique, statistiques, innovation', 'Santé', 'Bac+5/Doctorat', 400000.00, 2000000.00, 'ICA', 'En croissance', 0),
(37, 'Manipulateur en Imagerie Médicale', 'Réalisation d’examens médicaux utilisant des équipements d’imagerie', 'Le manipulateur en imagerie médicale réalise des examens comme les radiographies, scanners ou autres techniques d’imagerie sous la responsabilité des médecins spécialistes. Il prépare les patients et veille à la qualité des images obtenues.', 'Radiologie, imagerie médicale, scanner, radiographie, équipements médicaux, anatomie, relation patient', 'Santé', 'Bac+3', 300000.00, 1500000.00, 'RIS', 'Forte croissance', 1),
(38, 'Assistant Médical', 'Accompagnement des professionnels de santé dans la prise en charge des patients', 'L’assistant médical participe à l’organisation des consultations, accompagne les patients et aide les professionnels de santé dans certaines tâches administratives et médicales. Il contribue au bon fonctionnement des structures de soins.', 'Accueil patient, organisation médicale, assistance aux soins, dossiers médicaux, communication, hygiène médicale', 'Santé', 'Bac+2/Bac+3', 200000.00, 900000.00, 'SCR', 'Forte croissance', 1),
(39, 'Technicien en Pharmacie', 'Gestion et préparation des produits pharmaceutiques', 'Le technicien en pharmacie participe à la préparation, au stockage et à la gestion des produits pharmaceutiques. Il travaille sous la responsabilité des pharmaciens dans les pharmacies, hôpitaux ou structures de distribution.', 'Produits pharmaceutiques, gestion stock, préparation médicaments, réglementation, conseil patient, organisation', 'Santé', 'Bac+2/Bac+3', 200000.00, 900000.00, 'CSR', 'Stable', 1),
(40, 'Spécialiste Santé Publique', 'Gestion et amélioration des programmes de santé des populations', 'Le spécialiste en santé publique conçoit, coordonne et évalue des programmes visant à améliorer la santé des populations. Il intervient dans les ministères, ONG, organisations internationales et projets sanitaires.', 'Santé publique, gestion de projet, statistiques, prévention, politiques sanitaires, analyse de données, communication', 'Santé', 'Bac+5', 400000.00, 2500000.00, 'SIC', 'Forte croissance', 0),
(41, 'Architecte', 'Conception et réalisation de projets architecturaux', 'L’architecte imagine, conçoit et supervise la réalisation de bâtiments et d’espaces. Il transforme les besoins des clients en projets adaptés aux contraintes techniques, esthétiques et environnementales.', 'Conception architecturale, dessin technique, AutoCAD, modélisation 3D, créativité, réglementation bâtiment, gestion de projet', 'Génie Civil / BTP', 'Bac+5', 400000.00, 2500000.00, 'AIR', 'Forte croissance', 1),
(42, 'Conducteur de Travaux', 'Organisation et supervision des chantiers de construction', 'Le conducteur de travaux coordonne les différentes étapes d’un chantier. Il assure le suivi des équipes, des délais, des matériaux et de la qualité des travaux réalisés.', 'Gestion chantier, management équipe, planification, suivi travaux, sécurité, contrôle qualité, lecture de plans', 'Génie Civil / BTP', 'Bac+3/Bac+5', 350000.00, 2000000.00, 'RCE', 'Très forte croissance', 1),
(43, 'Ingénieur Structures', 'Conception et analyse des structures des bâtiments et ouvrages', 'L’ingénieur structures étudie la résistance et la stabilité des constructions. Il réalise des calculs techniques afin de garantir la sécurité et la durabilité des ouvrages.', 'Calcul structures, résistance des matériaux, béton armé, modélisation, logiciels techniques, analyse plans, normes construction', 'Génie Civil / BTP', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Forte croissance', 0),
(44, 'Ingénieur Hydraulique', 'Conception des systèmes liés à l’eau et aux infrastructures hydrauliques', 'L’ingénieur hydraulique travaille sur les projets liés à l’eau, l’assainissement et les ouvrages hydrauliques. Il participe à la gestion durable des ressources en eau.', 'Hydraulique, assainissement, gestion eau, calculs hydrauliques, études techniques, logiciels spécialisés', 'Génie Civil / BTP', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Très forte croissance', 0),
(45, 'Géomètre-Topographe', 'Mesure et étude des terrains pour les projets de construction', 'Le géomètre-topographe réalise des mesures précises des terrains afin de préparer les projets de construction, d’aménagement et d’infrastructures.', 'Topographie, cartographie, GPS, AutoCAD, relevés terrain, mesures, analyse spatiale', 'Génie Civil / BTP', 'Bac+2/Bac+3', 250000.00, 1200000.00, 'RIC', 'Forte croissance', 1),
(46, 'Technicien Génie Civil', 'Suivi technique et contrôle des travaux de construction', 'Le technicien génie civil participe à la réalisation et au suivi des projets de construction. Il aide à la préparation des plans, au contrôle des matériaux et au suivi des chantiers.', 'Lecture plans, contrôle travaux, matériaux construction, dessin technique, suivi chantier, sécurité', 'Génie Civil / BTP', 'Bac+2/Bac+3', 200000.00, 1000000.00, 'RCI', 'Forte croissance', 1),
(47, 'Dessinateur-Projeteur BTP', 'Réalisation de plans techniques pour les projets de construction', 'Le dessinateur-projeteur réalise les plans et représentations techniques nécessaires aux projets de bâtiment et de travaux publics à l’aide de logiciels spécialisés.', 'AutoCAD, DAO, modélisation 3D, dessin technique, plans bâtiment, logiciels conception', 'Génie Civil / BTP', 'Bac+2/Bac+3', 250000.00, 1200000.00, 'ARC', 'Forte croissance', 1),
(48, 'Urbaniste', 'Aménagement et organisation des espaces urbains', 'L’urbaniste analyse et participe à la planification des villes et territoires. Il contribue à créer des espaces adaptés aux besoins des populations et au développement durable.', 'Aménagement urbain, analyse territoire, cartographie, urbanisme, développement durable, gestion projet', 'Génie Civil / BTP', 'Bac+5', 400000.00, 2000000.00, 'IAS', 'En croissance', 1),
(49, 'Ingénieur Environnement et Construction Durable', 'Développement de solutions de construction respectueuses de l’environnement', 'L’ingénieur environnement spécialisé en construction durable accompagne les projets afin de réduire leur impact environnemental et améliorer leur efficacité énergétique.', 'Environnement, construction durable, efficacité énergétique, gestion déchets, normes environnementales, analyse risques', 'Génie Civil / BTP', 'Bac+5', 400000.00, 2000000.00, 'IRA', 'Très forte croissance', 1),
(50, 'Ingénieur Routes et Transports', 'Conception et gestion des infrastructures routières et de transport', 'L’ingénieur routes et transports participe aux études, à la conception et au suivi des infrastructures routières et des systèmes de transport. Il contribue au développement des réseaux de mobilité.', 'Routes, infrastructures transport, matériaux, études techniques, gestion projet, calculs, normes routières', 'Génie Civil / BTP', 'Bac+5', 400000.00, 2000000.00, 'RIC', 'Très forte croissance', 1),
(66, 'Chef de Chantier BTP', 'Gestion opérationnelle des équipes et du suivi des travaux sur les chantiers', 'Le chef de chantier organise les activités quotidiennes d’un chantier de construction. Il coordonne les équipes, contrôle l’avancement des travaux et veille au respect des règles de sécurité et de qualité.', 'Organisation chantier, management équipe, lecture plans, suivi travaux, sécurité, contrôle qualité', 'Génie Civil / BTP', 'Bac+2/Bac+3', 250000.00, 1200000.00, 'RCE', 'Très forte croissance', 0),
(67, 'Ingénieur Géotechnicien', 'Analyse des sols et étude des fondations des ouvrages', 'L’ingénieur géotechnicien étudie les caractéristiques des sols afin de garantir la stabilité des bâtiments, routes et infrastructures. Il intervient dans les études avant la construction des ouvrages.', 'Mécanique des sols, géologie, fondations, études terrain, calculs, analyse risques', 'Génie Civil / BTP', 'Bac+5', 450000.00, 2200000.00, 'IRC', 'Forte croissance', 0),
(68, 'Métreur / Économiste de la Construction', 'Estimation des coûts et gestion économique des projets de construction', 'Le métreur ou économiste de la construction évalue les quantités de matériaux, prépare les devis et participe à la maîtrise des coûts des projets BTP.', 'Métré, devis, estimation coûts, Excel, calcul quantités, analyse budget, appels offres', 'Génie Civil / BTP', 'Bac+2/Bac+3', 250000.00, 1500000.00, 'CRE', 'Forte croissance', 1),
(69, 'Électricien Bâtiment', 'Installation et maintenance des équipements électriques des bâtiments', 'L’électricien bâtiment réalise les installations électriques dans les logements, bâtiments professionnels et infrastructures. Il assure le câblage, le dépannage et la conformité des installations.', 'Électricité bâtiment, câblage, maintenance électrique, lecture schémas, sécurité électrique', 'Génie Civil / BTP', 'CAP/BT/Bac+2', 200000.00, 1000000.00, 'RCE', 'Forte croissance', 1),
(70, 'Ingénieur Électrique / Énergétique', 'Conception et gestion des systèmes électriques et énergétiques', 'L’ingénieur électrique ou énergétique conçoit et supervise des systèmes liés à l’électricité, aux énergies renouvelables et aux infrastructures énergétiques modernes.', 'Électricité, énergie solaire, réseaux électriques, efficacité énergétique, maintenance, études techniques', 'Génie Civil / BTP', 'Bac+5', 400000.00, 2500000.00, 'IRC', 'Très forte croissance', 0),
(71, 'Géomaticien BTP', 'Analyse des données géographiques pour les projets de construction et d’aménagement', 'Le géomaticien BTP utilise les systèmes d’information géographique et les données spatiales pour accompagner les projets de construction, d’aménagement urbain et d’infrastructures.', 'SIG, QGIS, ArcGIS, cartographie, GPS, télédétection, analyse spatiale, bases données géographiques', 'Génie Civil / BTP', 'Bac+3/Bac+5', 300000.00, 1800000.00, 'IRC', 'Forte croissance', 1),
(72, 'Logisticien', 'Organisation et optimisation des flux de marchandises et des opérations logistiques', 'Le logisticien organise le transport, le stockage et la distribution des marchandises. Il veille à la bonne circulation des produits entre les fournisseurs, les entreprises et les clients.', 'Gestion des flux, organisation transport, gestion stocks, planification, outils logistiques, analyse problèmes', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+2/Bac+3', 250000.00, 1500000.00, 'CRE', 'Très forte croissance', 1),
(73, 'Responsable Logistique', 'Supervision des activités logistiques d’une organisation', 'Le responsable logistique planifie et coordonne les opérations de transport, stockage et distribution afin d’améliorer les délais, les coûts et la qualité du service.', 'Management équipe, gestion transport, optimisation flux, gestion stocks, analyse performance, planification', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+3/Bac+5', 400000.00, 2500000.00, 'ECR', 'Très forte croissance', 0),
(74, 'Supply Chain Manager', 'Gestion stratégique de la chaîne d’approvisionnement', 'Le supply chain manager pilote l’ensemble de la chaîne logistique, depuis l’approvisionnement jusqu’à la livraison finale, afin d’optimiser la performance des entreprises.', 'Supply chain, analyse données, achats, gestion fournisseurs, stratégie logistique, optimisation coûts', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+5', 600000.00, 3000000.00, 'ECI', 'Très forte croissance', 0),
(75, 'Responsable Import-Export', 'Gestion des opérations commerciales internationales', 'Le responsable import-export organise les échanges internationaux de marchandises. Il assure le suivi des fournisseurs étrangers, des documents commerciaux et des procédures d’expédition.', 'Commerce international, négociation, réglementation douanière, gestion fournisseurs, langues étrangères, documentation', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+3/Bac+5', 400000.00, 2500000.00, 'ECR', 'Forte croissance', 1),
(76, 'Agent Transit / Déclarant en Douane', 'Gestion des procédures douanières et du passage des marchandises', 'L’agent transit accompagne les entreprises dans les formalités douanières, l’importation et l’exportation des marchandises.', 'Procédures douanières, réglementation, documents import-export, suivi marchandises, communication', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+2/Bac+3', 250000.00, 1500000.00, 'CER', 'Forte croissance', 1),
(77, 'Gestionnaire Transport', 'Organisation des opérations de transport de marchandises', 'Le gestionnaire transport planifie les déplacements des marchandises, optimise les itinéraires et assure le suivi des opérations de livraison.', 'Planification transport, gestion véhicules, suivi livraison, organisation, outils logistiques', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+2/Bac+3', 250000.00, 1500000.00, 'RCE', 'En croissance', 0),
(78, 'Responsable Approvisionnement', 'Gestion des achats et de la disponibilité des ressources', 'Le responsable approvisionnement sélectionne les fournisseurs, suit les commandes et garantit la disponibilité des produits nécessaires aux activités de l’entreprise.', 'Achats, négociation fournisseurs, gestion commandes, analyse besoins, gestion stocks', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+3/Bac+5', 350000.00, 2000000.00, 'ECR', 'Forte croissance', 0),
(79, 'Gestionnaire des Stocks', 'Contrôle et organisation des stocks d’une entreprise', 'Le gestionnaire des stocks assure le suivi des entrées et sorties de marchandises afin d’éviter les ruptures et les pertes.', 'Gestion stocks, inventaire, logiciels gestion, organisation, contrôle qualité', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+2/Bac+3', 200000.00, 1200000.00, 'CER', 'Stable', 1),
(80, 'Responsable Transport et Distribution', 'Supervision des activités de transport et de distribution', 'Le responsable transport et distribution organise les réseaux de livraison et supervise les opérations permettant d’acheminer les produits vers les clients.', 'Distribution, management, transport, analyse performance, organisation réseau', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+3/Bac+5', 400000.00, 2000000.00, 'ECR', 'Forte croissance', 0),
(81, 'Analyste Supply Chain', 'Analyse des données pour améliorer les performances logistiques', 'L’analyste supply chain utilise les données pour optimiser les coûts, les délais et les processus de la chaîne d’approvisionnement.', 'Analyse données, Excel, statistiques, tableaux de bord, supply chain, optimisation', 'Transport, Logistique, Commerce International et Supply Chain', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Très forte croissance', 1),
(82, 'Ingénieur Énergétique', 'Conception et gestion des systèmes énergétiques', 'L’ingénieur énergétique conçoit, analyse et améliore les systèmes de production et de consommation d’énergie. Il intervient notamment dans les énergies renouvelables, l’efficacité énergétique et les projets industriels.', 'Énergies renouvelables, solaire, efficacité énergétique, systèmes électriques, analyse énergétique, gestion de projet', 'Énergie, Mines et Industrie', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Très forte croissance', 1),
(83, 'Ingénieur Pétrole et Gaz', 'Gestion des activités liées aux ressources pétrolières et gazières', 'L’ingénieur pétrole et gaz participe à l’exploration, l’exploitation et l’optimisation des ressources pétrolières et gazières. Il travaille sur les installations, les procédés et la sécurité des opérations.', 'Génie pétrolier, géologie, exploitation, forage, analyse technique, sécurité industrielle', 'Énergie, Mines et Industrie', 'Bac+5', 700000.00, 4000000.00, 'IRC', 'Très forte croissance', 1),
(84, 'Ingénieur Mines et Géologie', 'Analyse et exploitation des ressources minières', 'L’ingénieur mines et géologie étudie les ressources du sous-sol et participe aux opérations d’extraction, d’exploitation et de gestion des sites miniers.', 'Géologie, exploitation minière, cartographie, analyse terrain, gestion projet, environnement', 'Énergie, Mines et Industrie', 'Bac+5', 500000.00, 3000000.00, 'RIC', 'Forte croissance', 1),
(85, 'Ingénieur Industriel', 'Optimisation des processus industriels', 'L’ingénieur industriel améliore les méthodes de production, l’organisation des entreprises industrielles et la performance des systèmes de fabrication.', 'Gestion production, optimisation processus, qualité, analyse industrielle, gestion projet, amélioration continue', 'Énergie, Mines et Industrie', 'Bac+5', 500000.00, 2500000.00, 'IRC', 'Forte croissance', 1),
(86, 'Ingénieur Maintenance Industrielle', 'Maintenance et amélioration des équipements industriels', 'L’ingénieur maintenance industrielle assure la disponibilité et la performance des machines et équipements utilisés dans les industries.', 'Mécanique industrielle, maintenance préventive, diagnostic équipements, gestion maintenance, fiabilité', 'Énergie, Mines et Industrie', 'Bac+5', 500000.00, 2500000.00, 'RIC', 'Très forte croissance', 0),
(87, 'Technicien Maintenance Industrielle', 'Entretien et réparation des équipements industriels', 'Le technicien maintenance industrielle intervient sur les machines et installations afin d’assurer leur fonctionnement et limiter les arrêts de production.', 'Électromécanique, maintenance, diagnostic panne, mécanique, électricité industrielle, sécurité', 'Énergie, Mines et Industrie', 'Bac+2/Bac+3', 250000.00, 1500000.00, 'RCE', 'Forte croissance', 1),
(88, 'Ingénieur Automatisme Industriel', 'Conception et gestion des systèmes automatisés', 'L’ingénieur automatisme industriel développe et supervise les systèmes permettant d’automatiser les machines et les processus industriels.', 'Automatisme, programmation industrielle, systèmes embarqués, robotique, instrumentation, contrôle industriel', 'Énergie, Mines et Industrie', 'Bac+5', 500000.00, 3000000.00, 'IRC', 'Très forte croissance', 1),
(89, 'Ingénieur HSE (Hygiène Sécurité Environnement)', 'Gestion de la sécurité et de l’environnement dans les organisations', 'L’ingénieur HSE met en place les politiques de prévention des risques, de sécurité au travail et de protection de l’environnement dans les secteurs industriels.', 'Sécurité industrielle, réglementation HSE, gestion risques, environnement, audit, prévention', 'Énergie, Mines et Industrie', 'Bac+3/Bac+5', 400000.00, 2500000.00, 'CSI', 'Forte croissance', 1),
(90, 'Responsable Production Industrielle', 'Gestion des opérations de production industrielle', 'Le responsable production industrielle organise et supervise les activités de fabrication afin d’atteindre les objectifs de qualité, coût et délai.', 'Management équipe, gestion production, planification, qualité, organisation industrielle', 'Énergie, Mines et Industrie', 'Bac+3/Bac+5', 400000.00, 2500000.00, 'ECR', 'Forte croissance', 1),
(91, 'Technicien Électromécanique Industrielle', 'Installation et maintenance des systèmes électromécaniques', 'Le technicien électromécanique industrielle installe, entretient et répare les équipements combinant électricité et mécanique dans les entreprises industrielles.', 'Électromécanique, moteurs, machines industrielles, électricité, maintenance, lecture plans techniques', 'Énergie, Mines et Industrie', 'Bac+2/Bac+3', 250000.00, 1500000.00, 'RCI', 'Forte croissance', 0),
(92, 'Ingénieur Agronome', 'Amélioration des systèmes de production agricole', 'L’ingénieur agronome accompagne la modernisation de l’agriculture en développant des techniques permettant d’améliorer les rendements, la qualité des productions et la gestion durable des ressources agricoles.', 'Agronomie, production végétale, gestion cultures, techniques agricoles, analyse sols, développement rural', 'Agriculture, Agroalimentaire et Environnement', 'Bac+5', 400000.00, 2000000.00, 'RIC', 'Forte croissance', 1),
(93, 'Ingénieur Agroalimentaire', 'Transformation et valorisation des produits agricoles', 'L’ingénieur agroalimentaire conçoit et améliore les procédés de transformation des produits agricoles afin de garantir la qualité, la sécurité alimentaire et l’efficacité des industries alimentaires.', 'Génie alimentaire, transformation aliments, qualité, sécurité alimentaire, procédés industriels, innovation', 'Agriculture, Agroalimentaire et Environnement', 'Bac+5', 400000.00, 2500000.00, 'IRC', 'Très forte croissance', 1),
(94, 'Technicien Agricole', 'Accompagnement technique des exploitations agricoles', 'Le technicien agricole conseille les producteurs, suit les cultures et participe à l’application des techniques modernes de production agricole.', 'Techniques agricoles, suivi cultures, conseil agricole, irrigation, fertilisation, terrain', 'Agriculture, Agroalimentaire et Environnement', 'Bac+2/Bac+3', 200000.00, 1000000.00, 'RSC', 'Forte croissance', 1),
(95, 'Responsable Production Agricole', 'Gestion des activités de production agricole', 'Le responsable production agricole organise les opérations d’une exploitation, supervise les équipes et optimise l’utilisation des ressources pour améliorer la production.', 'Gestion exploitation, management équipe, planification, production agricole, organisation', 'Agriculture, Agroalimentaire et Environnement', 'Bac+3/Bac+5', 300000.00, 1800000.00, 'REC', 'Forte croissance', 1),
(96, 'Ingénieur Environnement', 'Gestion et protection des ressources environnementales', 'L’ingénieur environnement analyse les impacts des activités humaines et développe des solutions pour protéger les ressources naturelles et favoriser un développement durable.', 'Gestion environnementale, analyse risques, traitement déchets, développement durable, réglementation', 'Agriculture, Agroalimentaire et Environnement', 'Bac+5', 400000.00, 2500000.00, 'IRC', 'Très forte croissance', 0),
(97, 'Spécialiste Développement Durable', 'Conception de projets liés au développement durable', 'Le spécialiste en développement durable accompagne les organisations dans la mise en place de stratégies responsables liées à l’environnement, aux ressources et aux impacts sociaux.', 'Développement durable, environnement, gestion projets, analyse impacts, responsabilité sociale', 'Agriculture, Agroalimentaire et Environnement', 'Bac+5', 400000.00, 2000000.00, 'SIA', 'Forte croissance', 0),
(98, 'Contrôleur Qualité Agroalimentaire', 'Contrôle de la qualité des produits alimentaires', 'Le contrôleur qualité agroalimentaire vérifie la conformité des produits alimentaires aux normes sanitaires et participe à l’amélioration des processus de production.', 'Contrôle qualité, normes alimentaires, hygiène, sécurité alimentaire, analyse laboratoire', 'Agriculture, Agroalimentaire et Environnement', 'Bac+3/Bac+5', 300000.00, 1800000.00, 'CIR', 'Très forte croissance', 1),
(99, 'Ingénieur Élevage et Productions Animales', 'Amélioration des systèmes d’élevage', 'L’ingénieur élevage travaille à l’amélioration des productions animales, à la gestion des élevages et au développement de solutions adaptées aux besoins agricoles.', 'Zootechnie, élevage, santé animale, production animale, gestion exploitation', 'Agriculture, Agroalimentaire et Environnement', 'Bac+5', 350000.00, 2000000.00, 'RIC', 'En croissance', 1),
(100, 'Technicien Agroalimentaire', 'Participation aux opérations de transformation alimentaire', 'Le technicien agroalimentaire intervient dans les unités de transformation, assure le suivi des procédés et participe au contrôle des produits alimentaires.', 'Transformation alimentaire, contrôle production, hygiène, procédés industriels, qualité', 'Agriculture, Agroalimentaire et Environnement', 'Bac+2/Bac+3', 250000.00, 1200000.00, 'RCI', 'Forte croissance', 1),
(101, 'Agripreneur', 'Création et gestion de projets agricoles innovants', 'L’agripreneur développe des activités agricoles, de transformation ou de commercialisation en utilisant des méthodes modernes pour créer de la valeur dans le secteur agricole.', 'Entrepreneuriat, gestion projet, agriculture moderne, commercialisation, innovation', 'Agriculture, Agroalimentaire et Environnement', 'Bac+2/Bac+5', 200000.00, 3000000.00, 'ECR', 'Très forte croissance', 1),
(102, 'Analyste Financier', 'Analyse des données financières et aide à la décision', 'L’analyste financier étudie la situation financière des entreprises et des organisations afin de produire des analyses utiles à la prise de décision et à l’évaluation des performances.', 'Analyse financière, Excel, modélisation financière, statistiques, comptabilité, analyse données', 'Banque, Finance, Assurance et Gestion', 'Bac+3/Bac+5', 400000.00, 2500000.00, 'IRC', 'Forte croissance', 1),
(103, 'Contrôleur de Gestion', 'Suivi des performances et contrôle budgétaire', 'Le contrôleur de gestion accompagne les entreprises dans le suivi des budgets, l’analyse des écarts et l’amélioration de la performance financière.', 'Gestion budgétaire, comptabilité analytique, Excel, analyse coûts, reporting, gestion performance', 'Banque, Finance, Assurance et Gestion', 'Bac+5', 400000.00, 2500000.00, 'CER', 'Forte croissance', 1),
(104, 'Auditeur Financier', 'Contrôle et vérification des informations financières', 'L’auditeur financier examine les comptes et les procédures des organisations afin de garantir leur fiabilité et leur conformité aux normes.', 'Audit, comptabilité, contrôle interne, analyse financière, normes comptables, rigueur', 'Banque, Finance, Assurance et Gestion', 'Bac+5', 400000.00, 3000000.00, 'CIR', 'Forte croissance', 1),
(105, 'Gestionnaire de Banque', 'Gestion des opérations et services bancaires', 'Le gestionnaire de banque assure le suivi des opérations bancaires, accompagne les clients et participe au développement des services financiers.', 'Produits bancaires, gestion clientèle, finance, analyse dossiers, communication, organisation', 'Banque, Finance, Assurance et Gestion', 'Bac+3/Bac+5', 300000.00, 1800000.00, 'CER', 'En croissance', 1),
(106, 'Chargé de Clientèle Banque', 'Accompagnement et conseil des clients bancaires', 'Le chargé de clientèle banque conseille les particuliers et entreprises, propose des solutions financières et développe la relation client.', 'Relation client, finance, communication, négociation, analyse besoins, produits bancaires', 'Banque, Finance, Assurance et Gestion', 'Bac+3', 250000.00, 1500000.00, 'ESC', 'Forte croissance', 1),
(107, 'Actuaire', 'Analyse des risques financiers et assurantiels', 'L’actuaire utilise les mathématiques et les statistiques pour évaluer les risques, prévoir les événements financiers et construire des solutions d’assurance.', 'Statistiques, probabilités, mathématiques financières, modélisation risques, analyse données', 'Banque, Finance, Assurance et Gestion', 'Bac+5', 500000.00, 3000000.00, 'IRC', 'Très forte croissance', 0),
(108, 'Analyste Crédit', 'Évaluation des demandes de financement', 'L’analyste crédit étudie les dossiers de financement afin d’évaluer les risques et la capacité de remboursement des clients ou entreprises.', 'Analyse crédit, finance, gestion risques, analyse financière, économie, dossiers clients', 'Banque, Finance, Assurance et Gestion', 'Bac+3/Bac+5', 300000.00, 2000000.00, 'ICR', 'Forte croissance', 1),
(109, 'Gestionnaire Assurance', 'Gestion des contrats et opérations d’assurance', 'Le gestionnaire assurance assure le suivi des contrats, traite les dossiers clients et participe à la gestion des risques assurantiels.', 'Assurance, gestion contrats, relation client, analyse risques, réglementation, organisation', 'Banque, Finance, Assurance et Gestion', 'Bac+3', 250000.00, 1800000.00, 'CER', 'En croissance', 1),
(110, 'Expert Finance Digitale et Fintech', 'Développement des solutions financières numériques', 'L’expert en finance digitale participe à la création et à l’amélioration des services financiers numériques comme les paiements mobiles et les plateformes financières.', 'Fintech, finance numérique, analyse données, technologies financières, innovation, gestion projet', 'Banque, Finance, Assurance et Gestion', 'Bac+5', 500000.00, 3000000.00, 'IRC', 'Très forte croissance', 1),
(111, 'Trésorier d’Entreprise', 'Gestion des flux financiers d’une organisation', 'Le trésorier d’entreprise assure la gestion de la trésorerie, le suivi des flux financiers et l’optimisation des ressources financières.', 'Gestion trésorerie, finance, analyse flux, Excel, prévisions financières, gestion risques', 'Banque, Finance, Assurance et Gestion', 'Bac+3/Bac+5', 350000.00, 2200000.00, 'CER', 'Forte croissance', 0),
(112, 'Juriste d’entreprise', 'Conseil juridique auprès des entreprises et organisations', 'Le juriste d’entreprise accompagne les organisations dans leurs activités juridiques. Il analyse les contrats, veille au respect des lois et conseille les dirigeants sur les aspects réglementaires.', 'Droit des affaires, analyse juridique, rédaction contrats, veille réglementaire, négociation', 'Administration publique, Économie et Sciences sociales', 'Bac+5', 300000.00, 2000000.00, 'ESA', 'Forte croissance', 1),
(113, 'Magistrat', 'Application du droit et administration de la justice', 'Le magistrat représente l’autorité judiciaire et participe au jugement des affaires conformément aux lois et aux principes de justice.', 'Droit, analyse juridique, raisonnement, décision, éthique professionnelle', 'Administration publique, Économie et Sciences sociales', 'Bac+5/+6', 500000.00, 3000000.00, 'ESA', 'Stable', 1),
(114, 'Administrateur public', 'Gestion des services et politiques publiques', 'L’administrateur public participe à la gestion des institutions publiques, à l’organisation des services de l’État et à la mise en œuvre des politiques publiques.', 'Administration publique, gestion projet, droit public, organisation, management', 'Administration publique, Économie et Sciences sociales', 'Bac+5', 400000.00, 2500000.00, 'ECR', 'Stable', 1),
(115, 'Inspecteur des finances publiques', 'Contrôle et gestion des ressources publiques', 'L’inspecteur des finances publiques contrôle l’utilisation des ressources publiques et participe à la bonne gestion financière des administrations.', 'Finance publique, contrôle, fiscalité, audit, analyse financière, réglementation', 'Administration publique, Économie et Sciences sociales', 'Bac+5', 400000.00, 2500000.00, 'CER', 'Stable', 1),
(116, 'Chargé de projet développement', 'Conception et suivi des projets de développement', 'Le chargé de projet développement accompagne les programmes économiques et sociaux menés par les institutions publiques, ONG et organismes internationaux.', 'Gestion projet, développement local, suivi-évaluation, analyse besoins, coordination', 'Administration publique, Économie et Sciences sociales', 'Bac+3/Bac+5', 300000.00, 2000000.00, 'EAS', 'Forte croissance', 1),
(117, 'Spécialiste Passation des Marchés Publics', 'Gestion des procédures d’achat public', 'Le spécialiste en passation des marchés publics prépare et suit les procédures d’acquisition des institutions publiques et organisations.', 'Droit public, marchés publics, réglementation, gestion contrats, analyse dossiers', 'Administration publique, Économie et Sciences sociales', 'Bac+3/Bac+5', 300000.00, 2000000.00, 'CER', 'Forte croissance', 1),
(118, 'Économiste', 'Analyse des phénomènes économiques et aide à la décision', 'L’économiste étudie les mécanismes économiques, analyse les données et produit des recommandations utiles aux entreprises, institutions publiques et organismes de développement.', 'Microéconomie, macroéconomie, statistiques, économétrie, analyse données, recherche', 'Administration publique, Économie et Sciences sociales', 'Bac+5', 400000.00, 2500000.00, 'IRC', 'Forte croissance', 1);
