(119, 'Sociologue', 'Analyse des comportements et phénomènes sociaux', 'Le sociologue étudie les sociétés, les comportements humains et les dynamiques sociales afin d’aider à comprendre et résoudre des problématiques collectives.', 'Recherche sociale, enquêtes, analyse données, sociologie, communication, études terrain', 'Administration publique, Économie et Sciences sociales', 'Bac+5', 250000.00, 1500000.00, 'SIA', 'Stable', 1),
(120, 'Analyste des politiques publiques', 'Évaluation et amélioration des politiques publiques', 'L’analyste des politiques publiques étudie les programmes publics, mesure leurs impacts et propose des améliorations pour les décideurs.', 'Analyse politiques publiques, statistiques, économie, recherche, évaluation programmes', 'Administration publique, Économie et Sciences sociales', 'Bac+5', 400000.00, 2500000.00, 'ISA', 'En croissance', 1),
(121, 'Gestionnaire de projet humanitaire', 'Organisation de programmes humanitaires et sociaux', 'Le gestionnaire de projet humanitaire coordonne les actions d’aide et de développement menées par les ONG et organisations internationales.', 'Gestion projet, développement international, coordination, communication, suivi-évaluation', 'Administration publique, Économie et Sciences sociales', 'Bac+3/Bac+5', 300000.00, 2000000.00, 'ESA', 'Forte croissance', 1),
(122, 'Enseignant / Professeur', 'Transmission des connaissances et accompagnement des apprenants', 'L’enseignant ou professeur transmet des connaissances, développe les compétences des élèves et participe à leur formation académique et professionnelle.', 'Pédagogie, communication, gestion classe, préparation cours, évaluation, discipline enseignée', 'Éducation, Formation et Recherche', 'Bac+3/Bac+5', 250000.00, 1500000.00, 'SIA', 'Stable', 1),
(123, 'Enseignant-chercheur', 'Enseignement supérieur et recherche scientifique', 'L’enseignant-chercheur exerce dans les universités et centres de recherche. Il combine l’enseignement, la production scientifique et l’encadrement des étudiants.', 'Recherche scientifique, enseignement supérieur, publication, analyse, encadrement, innovation', 'Éducation, Formation et Recherche', 'Bac+8', 500000.00, 3000000.00, 'ICA', 'En croissance', 1),
(124, 'Formateur professionnel', 'Formation des professionnels et développement des compétences', 'Le formateur professionnel accompagne les jeunes et les adultes dans l’acquisition de compétences techniques et professionnelles.', 'Animation formation, pédagogie, communication, accompagnement, conception supports', 'Éducation, Formation et Recherche', 'Bac+3/Bac+5', 250000.00, 1800000.00, 'SIA', 'Forte croissance', 1),
(125, 'Ingénieur pédagogique', 'Conception et amélioration des systèmes de formation', 'L’ingénieur pédagogique conçoit des méthodes d’apprentissage innovantes, notamment dans les formations numériques et l’enseignement à distance.', 'Ingénierie pédagogique, e-learning, outils numériques, conception cours, analyse besoins', 'Éducation, Formation et Recherche', 'Bac+5', 400000.00, 2500000.00, 'ISA', 'Très forte croissance', 1),
(126, 'Concepteur pédagogique numérique', 'Création de contenus éducatifs numériques', 'Le concepteur pédagogique numérique développe des ressources d’apprentissage adaptées aux plateformes digitales et aux nouvelles méthodes éducatives.', 'E-learning, création contenus, technologies éducatives, pédagogie, multimédia', 'Éducation, Formation et Recherche', 'Bac+3/Bac+5', 300000.00, 2000000.00, 'ASI', 'Très forte croissance', 1),
(127, 'Chercheur scientifique', 'Production de connaissances et innovation scientifique', 'Le chercheur scientifique mène des travaux de recherche dans différents domaines afin de produire de nouvelles connaissances et solutions.', 'Méthodologie recherche, analyse données, expérimentation, rédaction scientifique, innovation', 'Éducation, Formation et Recherche', 'Bac+5/Bac+8', 350000.00, 2500000.00, 'ICA', 'En croissance', 1),
(128, 'Conseiller d’orientation scolaire et professionnelle', 'Accompagnement des choix d’études et de carrière', 'Le conseiller d’orientation aide les élèves et étudiants à mieux comprendre leurs profils, leurs compétences et les possibilités de formation et de métiers.', 'Orientation, psychologie, accompagnement, analyse profils, communication, conseil', 'Éducation, Formation et Recherche', 'Bac+5', 300000.00, 2000000.00, 'SIA', 'Très forte croissance', 1),
(129, 'Responsable Formation', 'Gestion des programmes de formation', 'Le responsable formation organise les besoins en compétences, développe les plans de formation et accompagne les organisations dans le développement des talents.', 'Gestion formation, analyse besoins, gestion projet, ressources humaines, pédagogie', 'Éducation, Formation et Recherche', 'Bac+5', 400000.00, 2500000.00, 'ESA', 'Forte croissance', 1),
(130, 'Statisticien chercheur / Chargé d’études', 'Analyse de données pour la recherche et les études', 'Le statisticien chercheur exploite les données pour produire des analyses utiles aux institutions, chercheurs et organisations.', 'Statistiques, analyse données, enquêtes, méthodologie, logiciels statistiques, recherche', 'Éducation, Formation et Recherche', 'Bac+5', 400000.00, 2500000.00, 'IRC', 'Très forte croissance', 1),
(131, 'Chargé de communication', 'Gestion de la communication interne et externe des organisations', 'Le chargé de communication élabore les stratégies de communication, crée des contenus et assure la diffusion des informations auprès des différents publics.', 'Communication, rédaction, stratégie communication, gestion réseaux sociaux, relations médias, organisation', 'Communication, Médias, Culture et Création', 'Bac+3/Bac+5', 250000.00, 1800000.00, 'EAS', 'Forte croissance', 1),
(132, 'Journaliste', 'Collecte, analyse et diffusion de l’information', 'Le journaliste recherche, vérifie et présente des informations à travers différents supports comme la presse écrite, la radio, la télévision ou le numérique.', 'Investigation, rédaction, enquête, communication, analyse information, expression orale', 'Communication, Médias, Culture et Création', 'Bac+3/Bac+5', 200000.00, 1500000.00, 'IAS', 'Stable', 1),
(133, 'Community Manager', 'Gestion de la présence numérique des organisations', 'Le community manager anime les communautés en ligne, crée des contenus numériques et développe l’image des marques ou institutions sur les réseaux sociaux.', 'Réseaux sociaux, création contenu, communication digitale, analyse audience, créativité', 'Communication, Médias, Culture et Création', 'Bac+2/Bac+5', 200000.00, 1500000.00, 'ASI', 'Très forte croissance', 1),
(134, 'Graphiste Designer', 'Création de contenus visuels et supports graphiques', 'Le graphiste designer conçoit des identités visuelles, affiches, supports numériques et éléments graphiques pour les entreprises et organisations.', 'Design graphique, logiciels création, créativité, identité visuelle, communication visuelle', 'Communication, Médias, Culture et Création', 'Bac+2/Bac+3', 200000.00, 1500000.00, 'AIC', 'Forte croissance', 1),
(135, 'Designer Multimédia', 'Création de contenus numériques interactifs', 'Le designer multimédia réalise des contenus combinant images, vidéos, animations et éléments interactifs pour les supports numériques.', 'Design numérique, multimédia, audiovisuel, UX, création contenu, outils digitaux', 'Communication, Médias, Culture et Création', 'Bac+3/Bac+5', 250000.00, 2000000.00, 'ASI', 'Très forte croissance', 1),
(136, 'Réalisateur audiovisuel', 'Conception et réalisation de productions audiovisuelles', 'Le réalisateur audiovisuel dirige la création de films, documentaires, émissions ou contenus vidéo destinés aux médias et plateformes numériques.', 'Production audiovisuelle, scénario, direction artistique, montage, gestion équipe', 'Communication, Médias, Culture et Création', 'Bac+3/Bac+5', 250000.00, 2500000.00, 'AIS', 'En croissance', 1),
(137, 'Technicien audiovisuel', 'Gestion technique des productions audiovisuelles', 'Le technicien audiovisuel intervient dans la prise de son, l’image, l’éclairage et les équipements techniques utilisés dans les productions médias.', 'Prise de son, vidéo, équipements audiovisuels, montage, maintenance technique', 'Communication, Médias, Culture et Création', 'Bac+2/Bac+3', 200000.00, 1200000.00, 'RAC', 'En croissance', 1),
(138, 'Responsable événementiel', 'Organisation et gestion d’événements professionnels et culturels', 'Le responsable événementiel planifie et coordonne des événements comme des conférences, salons, manifestations culturelles ou commerciales.', 'Organisation événement, gestion projet, communication, logistique, négociation', 'Communication, Médias, Culture et Création', 'Bac+3/Bac+5', 250000.00, 2000000.00, 'EAS', 'Forte croissance', 1),
(139, 'Chargé des relations publiques', 'Gestion de l’image et des relations avec les publics', 'Le chargé des relations publiques développe les relations entre une organisation, ses partenaires, les médias et ses différents publics.', 'Relations publiques, communication, négociation, stratégie image, rédaction', 'Communication, Médias, Culture et Création', 'Bac+3/Bac+5', 250000.00, 1800000.00, 'ESA', 'En croissance', 1),
(140, 'Responsable hôtelier', 'Gestion et supervision des activités d’un établissement hôtelier', 'Le responsable hôtelier organise les services d’un hôtel, supervise les équipes et veille à la qualité de l’accueil et de l’expérience client.', 'Management hôtelier, gestion équipe, relation client, organisation, qualité de service', 'Tourisme, Hôtellerie et Restauration', 'Bac+2/Bac+5', 300000.00, 2000000.00, 'EAS', 'Forte croissance', 1),
(141, 'Directeur d’hôtel', 'Direction stratégique et opérationnelle d’un établissement hôtelier', 'Le directeur d’hôtel pilote l’ensemble des activités d’un établissement, de la gestion financière à la qualité des services proposés.', 'Leadership, gestion, finance, management, stratégie commerciale, organisation', 'Tourisme, Hôtellerie et Restauration', 'Bac+3/Bac+5', 500000.00, 4000000.00, 'ECR', 'En croissance', 0),
(142, 'Réceptionniste hôtelier', 'Accueil et accompagnement des clients dans un établissement hôtelier', 'Le réceptionniste hôtelier assure l’accueil des clients, les réservations et la coordination avec les différents services de l’hôtel.', 'Accueil, communication, langues étrangères, gestion réservation, relation client', 'Tourisme, Hôtellerie et Restauration', 'Bac+2', 200000.00, 1000000.00, 'SCE', 'Stable', 1),
(143, 'Agent de voyage / Conseiller voyage', 'Organisation et conseil dans les prestations touristiques', 'L’agent de voyage accompagne les clients dans la préparation de leurs déplacements, réservations et choix de destinations.', 'Organisation voyage, réservation, conseil client, tourisme, communication', 'Tourisme, Hôtellerie et Restauration', 'Bac+2/Bac+3', 200000.00, 1500000.00, 'ESA', 'En croissance', 1),
(144, 'Guide touristique professionnel', 'Accompagnement et valorisation du patrimoine touristique', 'Le guide touristique professionnel présente les sites culturels, historiques et naturels aux visiteurs tout en assurant leur accompagnement.', 'Culture, histoire, communication, langues, animation, connaissance territoire', 'Tourisme, Hôtellerie et Restauration', 'Bac+2/Bac+3', 200000.00, 1200000.00, 'ESA', 'En croissance', 1),
(145, 'Responsable restauration', 'Gestion d’un service ou établissement de restauration', 'Le responsable restauration organise les activités d’un restaurant, supervise les équipes et garantit la qualité des prestations.', 'Gestion restauration, management, organisation, contrôle qualité, gestion coûts', 'Tourisme, Hôtellerie et Restauration', 'Bac+2/Bac+3', 300000.00, 2000000.00, 'ECR', 'Forte croissance', 1),
(146, 'Chef cuisinier professionnel', 'Préparation et création de prestations culinaires professionnelles', 'Le chef cuisinier professionnel dirige la cuisine d’un établissement et développe des créations culinaires adaptées aux exigences des clients.', 'Cuisine professionnelle, créativité, organisation cuisine, gestion équipe, hygiène alimentaire', 'Tourisme, Hôtellerie et Restauration', 'Bac+1/Bac+2', 200000.00, 2000000.00, 'RAC', 'En croissance', 1),
(147, 'Pâtissier professionnel', 'Création de produits de pâtisserie dans un cadre professionnel', 'Le pâtissier professionnel réalise des produits sucrés pour les hôtels, restaurants, entreprises alimentaires ou activités entrepreneuriales.', 'Pâtisserie, créativité, précision, hygiène alimentaire, techniques culinaires', 'Tourisme, Hôtellerie et Restauration', 'Bac+1/Bac+2', 200000.00, 1500000.00, 'RAC', 'En croissance', 1),
(148, 'Assistant comptable', 'Assistance dans la gestion des opérations comptables quotidiennes', 'L’assistant comptable participe à la saisie des opérations, au suivi des documents financiers et à la préparation des travaux comptables.', 'Saisie comptable, logiciels comptables, organisation, contrôle documents, rigueur', 'Comptabilité, Fiscalité et Expertise', 'Bac+2/Bac+3', 200000.00, 1000000.00, 'CER', 'Stable', 1),
(149, 'Expert-comptable', 'Expertise avancée en comptabilité et conseil financier', 'L’expert-comptable accompagne les entreprises dans la tenue des comptes, la conformité financière et le conseil en gestion.', 'Comptabilité supérieure, normes comptables, fiscalité, conseil, analyse financière', 'Comptabilité, Fiscalité et Expertise', 'Bac+5/Bac+8', 500000.00, 4000000.00, 'IRC', 'Forte croissance', 1),
(150, 'Fiscaliste', 'Spécialiste de la fiscalité des entreprises et organisations', 'Le fiscaliste conseille les entreprises sur leurs obligations fiscales et optimise leur situation dans le respect de la réglementation.', 'Droit fiscal, fiscalité entreprise, analyse réglementation, conseil', 'Comptabilité, Fiscalité et Expertise', 'Bac+5', 350000.00, 2500000.00, 'CER', 'Forte croissance', 1),
(151, 'Comptable public', 'Gestion comptable dans les administrations publiques', 'Le comptable public assure le suivi des opérations financières des organismes publics et le respect des règles budgétaires.', 'Comptabilité publique, finances publiques, contrôle administratif, gestion budget', 'Comptabilité, Fiscalité et Expertise', 'Bac+3/Bac+5', 300000.00, 2000000.00, 'CER', 'Stable', 1),
(152, 'Collaborateur de cabinet comptable', 'Accompagnement des entreprises dans leurs missions comptables', 'Le collaborateur de cabinet comptable réalise des missions de tenue comptable, déclarations fiscales et accompagnement des clients.', 'Comptabilité, fiscalité, relation client, logiciels comptables, analyse documents', 'Comptabilité, Fiscalité et Expertise', 'Bac+2/Bac+5', 250000.00, 2000000.00, 'CER', 'Forte croissance', 0),
(153, 'Spécialiste normes comptables IFRS', 'Expert des normes comptables internationales', 'Le spécialiste IFRS accompagne les organisations dans l’application des normes comptables internationales et la conformité financière.', 'Normes IFRS, comptabilité internationale, analyse financière, reporting', 'Comptabilité, Fiscalité et Expertise', 'Bac+5', 500000.00, 3000000.00, 'IRC', 'En croissance', 0),
(154, 'Spécialiste marketing digital', 'Développement des stratégies marketing utilisant les outils numériques.', 'Le spécialiste marketing digital accompagne les organisations dans leur visibilité en ligne, la promotion des produits et l’analyse des comportements des clients.', 'Marketing digital, réseaux sociaux, publicité en ligne, analyse données, stratégie numérique', 'Commerce, Marketing et Communication', 'Bac+3/Bac+5', 250000.00, 2000000.00, 'EAS', 'Très forte croissance', 1),
(155, 'Commercial', 'Développement des ventes et gestion de la relation client.', 'Le commercial représente une entreprise auprès des clients, présente ses produits ou services et développe son portefeuille commercial.', 'Vente, négociation, prospection, communication, relation client', 'Commerce, Marketing et Communication', 'Bac+2/Bac+3', 200000.00, 1500000.00, 'ECS', 'Stable', 1),
(156, 'Business developer', 'Création de nouvelles opportunités commerciales pour les entreprises.', 'Le business developer recherche de nouveaux marchés, développe des partenariats et participe à la croissance des organisations.', 'Développement commercial, négociation, stratégie, entrepreneuriat, analyse marché', 'Commerce, Marketing et Communication', 'Bac+3/Bac+5', 300000.00, 2500000.00, 'ECR', 'Très forte croissance', 1),
(157, 'Spécialiste e-commerce', 'Gestion et développement des activités commerciales en ligne.', 'Le spécialiste e-commerce développe les ventes sur internet et accompagne les entreprises dans leur transformation commerciale numérique.', 'Commerce électronique, plateformes web, marketing digital, gestion produits, analyse ventes', 'Commerce, Marketing et Communication', 'Bac+3/Bac+5', 250000.00, 2000000.00, 'EAS', 'Très forte croissance', 1),
(158, 'Communicateur commercial', 'Création de stratégies de communication orientées vers les objectifs commerciaux.', 'Le communicateur commercial conçoit des messages et supports destinés à promouvoir les produits, services et marques.', 'Communication, création contenu, image de marque, stratégie commerciale', 'Commerce, Marketing et Communication', 'Bac+3/Bac+5', 250000.00, 1800000.00, 'ESA', 'Forte croissance', 0),
(159, 'Entrepreneur / Consultant en développement commercial', 'Création ou accompagnement des activités commerciales.', 'Ce professionnel développe des projets commerciaux, accompagne les entreprises et contribue à leur croissance.', 'Entrepreneuriat, stratégie commerciale, gestion projet, innovation, négociation', 'Commerce, Marketing et Communication', 'Bac+3/Bac+5', 0.00, 3000000.00, 'ECR', 'Très forte croissance', 1),
(160, 'Ingénieur télécommunications', 'Conception et gestion des infrastructures de télécommunications.', 'L’ingénieur télécommunications développe, déploie et supervise les réseaux de communication fixes et mobiles.', 'Télécommunications, réseaux, transmission, communication numérique, résolution de problèmes', 'Télécommunications et Réseaux', 'Bac+5', 400000.00, 3500000.00, 'IRC', 'Très forte croissance', 1),
(161, 'Technicien réseaux et télécommunications', 'Installation et maintenance des équipements réseaux et télécoms.', 'Le technicien intervient sur les infrastructures réseau, les équipements de communication et les systèmes de transmission.', 'Maintenance réseau, câblage, configuration équipements, diagnostic technique', 'Télécommunications et Réseaux', 'Bac+2/Bac+3', 200000.00, 1200000.00, 'RIC', 'En croissance', 1),
(162, 'Ingénieur réseaux mobiles (4G/5G)', 'Conception et optimisation des réseaux de téléphonie mobile.', 'Ce professionnel participe au déploiement et à l’amélioration des réseaux mobiles nouvelle génération.', 'Réseaux mobiles, télécommunications, radio, optimisation réseau', 'Télécommunications et Réseaux', 'Bac+5', 450000.00, 4000000.00, 'IRC', 'Très forte croissance', 1),
(163, 'Architecte réseaux', 'Conception des architectures réseaux des organisations.', 'L’architecte réseaux définit les infrastructures permettant de garantir la performance, la sécurité et la disponibilité des réseaux.', 'Architecture réseau, cybersécurité, infrastructures, administration réseau', 'Télécommunications et Réseaux', 'Bac+5', 500000.00, 4500000.00, 'IRC', 'Très forte croissance', 0),
(164, 'Technicien fibre optique', 'Installation et maintenance des réseaux en fibre optique.', 'Le technicien fibre optique assure le déploiement et la maintenance des infrastructures de fibre optique.', 'Fibre optique, installation, maintenance, câblage, diagnostic', 'Télécommunications et Réseaux', 'Bac+2', 200000.00, 1000000.00, 'RIC', 'Forte croissance', 1),
