(166, 'Ingénieur transmission', 'Conception et supervision des systèmes de transmission de données.', 'L’ingénieur transmission assure la fiabilité des échanges de données sur les infrastructures de télécommunications.', 'Transmission de données, réseaux, télécommunications, analyse technique', 'Télécommunications et Réseaux', 'Bac+5', 400000.00, 3500000.00, 'IRC', 'Très forte croissance', 0),
(167, 'Gestionnaire des ressources humaines', 'Gestion administrative et humaine des organisations.', 'Le gestionnaire des ressources humaines accompagne les organisations dans la gestion du personnel, le développement des compétences et l’application du droit du travail.', 'Gestion RH, droit du travail, organisation, communication, administration', 'Ressources Humaines et Développement Organisationnel', 'Bac+3/Bac+5', 300000.00, 2500000.00, 'ESA', 'Forte croissance', 1),
