(172, 'Assistant de direction', 'Professionnel chargé d’assister un dirigeant dans l’organisation administrative, la gestion des dossiers et la coordination des activités.', 'Il facilite le fonctionnement quotidien d’une entreprise en assurant le suivi administratif, la planification et la communication.', 'Organisation,Bureautique,Communication,Gestion administrative,Planification', 'Économie et Gestion', 'Bac+2/Bac+3', 250000.00, 700000.00, 'CES', 'Forte demande', 1),
